var SYS_NARRATION = {bleed:[{text:"Welcome to the bleed air system walkthrough. The Falcon 50 has three Honeywell TFE731 engines, and each one supplies bleed air to power the air conditioning, pressurization, anti-ice, and fuel tank systems.",highlight:null},{text:"Let's start with engine one, on the right pod. It supplies low-pressure bleed to the common manifold for cabin air, and high-pressure bleed for the right wing anti-ice system.",highlight:"eng1"},{text:"Engine two is the center engine with the S-duct intake. Its low-pressure bleed feeds the manifold, and its high-pressure bleed is used to anti-ice the S-duct itself.",highlight:"eng2"},{text:"Engine three is on the left pod, supplying both bleed types just like engine one. High-pressure bleed from engines one and three together drive the airframe wing anti-ice.",highlight:"eng3"},{text:"The APU on the ground provides bleed air for engine start and pre-flight air conditioning. Once engines are running, the APU bleed is turned off and you switch to engine bleed.",highlight:"apu"},{text:"The ISO valve, in the middle of the bleed manifold, can split the manifold into two halves. You'd close it during a bleed leak to isolate which side has the problem.",highlight:"iso"},{text:"The PRV — pressure regulating valve — opens engine 2's bleed to assist the cabin air conditioning packs during hot days or climb. It's normally in AUTO.",highlight:"prv"},{text:"The bleed manifold feeds the crew air conditioning pack, the cabin air conditioning pack, the S-duct anti-ice, the wing anti-ice, and tank pressurization. Try toggling the ISO valve closed and watch the right side keep flowing while the left half cuts off.",highlight:"iso"},{text:"If you see smoke or a bleed leak, the procedure is to close the ISO valve and turn off the affected side. The diagram will show you which components stay powered. That completes the bleed air walkthrough.",highlight:null}],dcelec:[{text:"Welcome to the Falcon 50 DC electrical system. This is the most commonly misunderstood system on the airplane, so let's get it right.",highlight:null},{text:"There are three engine-driven generators, one per engine, plus two batteries and an APU generator. The architecture is split left and right — not by engine number.",highlight:null},{text:"Generator one and generator two both feed the Left Main DC bus. This is the key fact to remember: generator two does not power its own bus, it backs up generator one.",highlight:"gen1"},{text:"Generator three is the only generator that feeds the Right Main DC bus. If you lose generator three, you must tie the bus tie switch to repower the right side from the left.",highlight:"gen3"},{text:"The Left Main DC bus feeds the A bus and the auxiliary C bus, plus the left windshield heat and the standby hydraulic pump.",highlight:"lMain"},{text:"The Right Main DC bus feeds the B bus and the auxiliary D bus, plus the right windshield heat. Critically, the antiskid system is on the B bus — lose right main, you lose antiskid.",highlight:"rMain"},{text:"The C bus powers the flaps, rudder trim, and emergency aileron trim. The D bus powers the nose wheel steering and normal aileron trim. You can switch C or D off to conserve battery in an emergency.",highlight:"cBus"},{text:"Try selecting the GEN 3 INOP scenario, then toggle the bus tie to TIED. Watch the right side regain power. This is the exact procedure from emergency checklist E-41.",highlight:"busTie"},{text:"In a three-generators-inoperative emergency, batteries provide about 20 minutes at 50 amps each, which is why you load-shed the C and D buses immediately.",highlight:null},{text:"That covers DC electrical. Remember: left versus right, not one-two-three.",highlight:null}],hyd:[{text:"The Falcon 50 has three independent hydraulic systems, each pressurized to 3000 psi with MIL-H-5606 fluid.",highlight:null},{text:"Engine 1 drives Hydraulic System 1 — the primary system. System 1 powers the main flight controls, normal brakes with antiskid, and nose wheel steering.",highlight:"sys1"},{text:"Engine 3 drives Hydraulic System 2. System 2 runs in parallel with System 1 on the primary flight controls, and it's also the emergency brake source.",highlight:"sys2"},{text:"Engine 2, the center engine, drives Hydraulic System 3. System 3 powers nose wheel steering, airbrakes, landing gear, flaps and slats, and the thrust reverser.",highlight:"sys3"},{text:"Notice that the system number does not match the engine number. This is the most common oral exam trap on the Falcon 50.",highlight:null},{text:"There is also an electric standby pump, powered from the Left Main DC bus. It backs up System 1 and provides emergency operation for slats, gear, and brake accumulators. Max altitude for standby pump operation is 45,000 feet.",highlight:"stby"},{text:"If you lose any single hydraulic system, maximum airspeed is 260 knots or Mach 0.76. Try the Loss of System 1 scenario and watch the brakes turn yellow — you would switch the brake selector to EMER, which uses System 2.",highlight:"brakes"},{text:"The N114TD Greenville accident in 2018 is the standing lesson here. The crew had an antiskid failure and didn't select EMER brake — they overran the runway. Antiskid failure on rollout means brake selector goes to EMER immediately and you modulate manually.",highlight:"brakes"},{text:"If both hydraulic systems fail, manual reversion is possible but controls become heavy. Plan a flaps-up or partial-flap landing on the longest runway available.",highlight:null}],fuel:[{text:"The Falcon 50 fuel system has three independent tanks — left wing, center, and right wing — totaling about fifteen thousand five hundred pounds.",highlight:null},{text:"Each wing tank holds approximately five thousand one hundred fifty pounds. The center tank holds five thousand two hundred ten pounds.",highlight:"cWing"},{text:"Each engine has its own collector tank, called a feeder, and each feeder has a boost pump that delivers fuel to the engine. Transfer pumps move fuel from the wing tanks down to the feeders.",highlight:"feed1"},{text:"Here's a key training point: the center tank does not actively transfer in normal operation. It gravity-feeds the number one and number two feeders only when those feeders drop below approximately six hundred pounds.",highlight:"cWing"},{text:"So on a long leg, you may see the center tank just sitting there for the first part of cruise — that's expected.",highlight:null},{text:"To manage a lateral imbalance, the primary tool is to turn off the transfer pump on the heavy side. Let the engines burn down that feeder. Crossfeed is the secondary tool, not the primary.",highlight:"xfr1"},{text:"If a boost pump fails, the engine will still run on suction feed with slightly reduced fuel pressure. Try the Boost 1 Fail scenario and you'll see boost pump 1 turn red, but the engine continues to run.",highlight:"bst1"},{text:"Fuel computers must be operational for takeoff per the AFM, with limited exceptions in Annex 5.",highlight:null},{text:"That completes the fuel system walkthrough.",highlight:null}],fc:[{text:"The Falcon 50 flight controls are hydraulically powered. Ailerons, elevator, and rudder all receive boost from hydraulic systems one and two in parallel.",highlight:"ail"},{text:"Arthur Q is the dynamic pressure feel system. It makes the elevator forces light at low speed and heavy at high speed. Don't pull aggressively on rotation — the column feels light at V-R because of Arthur Q.",highlight:"arthurQ"},{text:"Mach trim engages between 0.78 and 0.89 Mach, commanding about 0.4 degrees of nose-up stabilizer to compensate for Mach tuck. If Mach trim fails and autopilot is off, maximum speed is 0.78 Mach.",highlight:"machtrim"},{text:"The yaw damper must be centered for takeoff. It uses hydraulic actuators on the rudder and is integrated with the autopilot.",highlight:"yawDamp"},{text:"Slats and flaps. The Falcon 50 has leading-edge slats and trailing-edge flaps with two detents — 20 degrees and 48 degrees.",highlight:"slats"},{text:"Speed limits to memorize: slats extended, 200 knots. Slats plus flaps 20, 190 knots. Slats plus flaps 48, 175 knots. Maximum altitude with slats or flaps extended is 20,000 feet.",highlight:"flaps"},{text:"Auto-slat is alpha-driven, meaning the slats deploy automatically at high angle of attack regardless of selector position. With auto-slat light on, maximum airspeed is 270 knots.",highlight:"slats"},{text:"Flap asymmetry protection trips the control circuit breaker at a 5-degree split with flaps 20, or 8-degree split with flaps 48. The flaps freeze in place — land in whatever configuration you have.",highlight:"flaps"},{text:"Airbrakes auto-retract when you advance the thrust levers, and they are not recommended within 500 feet AGL.",highlight:"ab"}],ai:[{text:"Anti-ice walkthrough. Icing conditions on the ground exist when outside air temperature is below 10 degrees Celsius with visible moisture. In flight, icing exists at total air temperature of 10 degrees.",highlight:null},{text:"Engine anti-ice uses high-pressure bleed routed to the nacelle inlet. For engine 2, it also feeds the S-duct intake.",highlight:"eng2AI"},{text:"Wing anti-ice is driven by high-pressure bleed from engines one and three together. If you lose either engine 1 or engine 3, your wing anti-ice capacity is halved — avoid icing if possible.",highlight:"wingAI"},{text:"Engine and wing anti-ice are prohibited with outside air temperature above 10 degrees Celsius. Wing anti-ice on the ground is limited to short-duration testing only — to verify the valves work, not to actually heat the wing.",highlight:"wingAI"},{text:"Windshield heat is electrical, not pneumatic. Left windshield is powered by the Left Main DC bus, right windshield from the Right Main DC bus.",highlight:"wshld"},{text:"Pitot and angle-of-attack heat are also electrical, split across the A and B buses. Pitot heat must be on for takeoff.",highlight:"pitot"},{text:"When you enter icing, the standard flow is engine anti-ice on first, then airframe anti-ice, then windshield heat. That completes anti-ice.",highlight:null}],pp:[{text:"Powerplant walkthrough. The Falcon 50 has three Honeywell TFE 731-3-1C turbofan engines, each rated at 3,700 pounds of static thrust at sea level on a standard day.",highlight:"eng1"},{text:"Important: the dash-3-1-C is hydromechanical only. There is no DEEC or FADEC. Hot-start protection is entirely pilot vigilance plus the ITT gauge. The 50EX uses the dash-4-0 engines, which do have digital control — different airplane.",highlight:"fcc1"},{text:"N1 is the thrust setting parameter. Maximum N1 for takeoff and max continuous is 101.5 percent. Maximum N2 is 100 percent.",highlight:"eng1"},{text:"ITT — interstage turbine temperature, not EGT — is the temperature you watch. Maximum during takeoff is 907 degrees for 5 minutes. Max continuous is 885. During start, the transient limit is 927 for 10 seconds.",highlight:"eng1"},{text:"Oil pressure: 38 to 46 PSI during takeoff and continuous operation, with 25 PSI minimum at idle. Below 25 PSI triggers the oil light.",highlight:"eng1"},{text:"Engine 2, the center engine, is the only one with a thrust reverser — clamshell type, ground only, maximum 30 seconds continuous, 4.5 minutes between consecutive uses.",highlight:"eng2"},{text:"Engine sync syncs the outboard engines to engine 2 — the master. Sync is inhibited for takeoff, landing, and missed approach.",highlight:"sync"},{text:"APU is the GTCP36-100. Ground use only. Maximum rated N1 is 100 percent, 110 percent allowable. ITT max rated 680, max allowable 732. 300 amp generator output. Cannot start or run in flight.",highlight:"apu"}],gear:[{text:"Landing gear walkthrough. Tricycle gear, hydraulically actuated. The nose gear retracts forward, main gear retracts inboard.",highlight:"nose"},{text:"Hydraulic System 3, driven by engine 2, powers the normal gear operation. If you lose System 3, gear extension is by free-fall gravity — takes about 2 minutes to fully extend.",highlight:"rev"},{text:"Speed limits: VLO 190 knots for gear operation. VLE 220 knots when extended. Tire ground speed limit is 180 knots.",highlight:null},{text:"Nose wheel steering is also on Hydraulic System 3. Maximum steering angle is 60 degrees. If you lose System 3, you taxi with differential braking and asymmetric thrust.",highlight:"nose"},{text:"Brakes: System 1 provides normal braking with antiskid. Antiskid requires B bus power — that's the link to electrical that matters here.",highlight:"lMain"},{text:"The brake selector switches to EMER position to use System 2 accumulator pressure. There is NO antiskid in EMER mode — you must modulate brakes manually to prevent tire blowouts.",highlight:"antiskid"},{text:"Now the N114TD lesson. In September 2018, a Falcon 50 at Greenville South Carolina had an antiskid failure on rollout. The crew did not select EMER brake. They overran a 5,393-foot runway and both pilots died.",highlight:"antiskid"},{text:"Anti-skid failure on rollout means EMER brake immediately, then modulate manually. Consider parking brake as a last resort if directional control allows.",highlight:"brakeAcc"},{text:"The thrust reverser is on engine 2 only. Maximum N1 in reverse is 93 percent, 30 seconds continuous, 4.5 minutes between consecutive uses. Once you've selected reverse, you cannot attempt a go-around.",highlight:"rev"}],acelec:[{text:"AC electrical system. The Falcon 50 has two static inverters, each rated at 750 VA maximum.",highlight:"inv1"},{text:"Inverter 1 is powered from the C bus, which traces back to the Left Main DC bus. Its output feeds AC Bus 1, which serves the primary flight instruments — EFIS, gyros, and nav radios.",highlight:"inv1"},{text:"Inverter 2 is powered from the D bus, which traces back to the Right Main DC bus. Its output feeds AC Bus 2, serving secondary loads — galley, heat, pumps.",highlight:"inv2"},{text:"If you lose inverter 1 you lose your primary flight instruments and need to revert to standby. If you lose both inverters, only the standby instruments remain.",highlight:"ac1"},{text:"Both inverters can be cross-tied to provide backup, per the abnormal procedures.",highlight:null}]};

var INTERACTIVE = {bleed:{title:"Pneumatics / Bleed Air",def:BLEED_SYS,handbook:"bleed"},env:{title:"Environmental / Pressurization",def:BLEED_SYS,handbook:"bleed"},dcelec:{title:"Electrical (DC)",def:DCELEC_SYS,handbook:"dcelec"},acelec:{title:"Electrical (AC)",def:ACELEC_SYS,handbook:"acelec"},fuel:{title:"Fuel",def:FUEL_SYS,handbook:"fuel"},hyd:{title:"Hydraulics",def:HYD_SYS,handbook:"hyd"},fc:{title:"Flight Controls",def:FC_SYS,handbook:null},ai:{title:"Anti-Ice",def:AI_SYS,handbook:null},pp:{title:"Powerplant + APU",def:PP_SYS,handbook:null},gear:{title:"Landing Gear + Brakes",def:GEAR_SYS,handbook:null}};

export { INTERACTIVE, SYS_NARRATION, AudioController };
